local GlassFurnaceMaker = {}
local PRODUCTS = {
    simple_brick_glass_furnace = { name = "Preprosta opečna steklarska peč", brickCost = 4, clayCost = 2, woodCost = 2, time = 8, cost = 300, science = 25, happiness = 1, description = "Preprosta opečna steklarska peč za taljenje stekla." },
    iron_reinforced_furnace = { name = "Železnookrepljena steklarska peč", brickCost = 3, ironCost = 2, clayCost = 2, woodCost = 2, time = 11, cost = 680, science = 40, happiness = 2, prestige = 2, description = "Železnookrepljena steklarska peč za trgovce." },
    silver_banded_furnace = { name = "Srebrnopasna steklarska peč", brickCost = 3, silverCost = 1, ironCost = 2, clayCost = 2, woodCost = 2, time = 15, cost = 1500, science = 55, happiness = 2, prestige = 6, description = "Srebrnopasna steklarska peč za plemiče." },
    gold_trimmed_furnace = { name = "Zlatookrasna steklarska peč", brickCost = 3, goldCost = 1, silverCost = 1, ironCost = 2, clayCost = 2, woodCost = 2, time = 19, cost = 3400, science = 70, happiness = 3, prestige = 14, description = "Zlatookrasna steklarska peč za visoke plemiče." },
    jewel_set_furnace = { name = "Draguljasta steklarska peč", brickCost = 3, goldCost = 1, silverCost = 1, ironCost = 2, clayCost = 2, woodCost = 2, jewelCost = 1, time = 23, cost = 7200, science = 85, happiness = 5, prestige = 27, description = "Steklarska peč z draguljem za visoko plemstvo." },
    royal_grand_glass_furnace = { name = "Kraljevski veliki steklarska peč", brickCost = 5, goldCost = 2, silverCost = 2, ironCost = 2, clayCost = 2, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 30, cost = 15000, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska steklarska peč z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    furnace_workshop = { name = "Pečna delavnica", cost = { gold = 340, wood = 160, stone = 200, brick = 8, clay = 8 }, upkeep = 8, qualityBonus = 5 },
    glassworks_loft = { name = "Steklarska podstrešje", cost = { gold = 1200, wood = 320, stone = 360, silver = 6, iron = 6 }, upkeep = 28, qualityBonus = 18 },
    master_furnace_atelier = { name = "Mojstrski pečni atelje", cost = { gold = 3000, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    royal_glassworks_palace = { name = "Kraljevska steklarska palača", cost = { gold = 13000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
GlassFurnaceMaker.brickStock = 18; GlassFurnaceMaker.clayStock = 12; GlassFurnaceMaker.woodStock = 14; GlassFurnaceMaker.ironStock = 12; GlassFurnaceMaker.silverStock = 6; GlassFurnaceMaker.goldStock = 6; GlassFurnaceMaker.jewelStock = 4; GlassFurnaceMaker.pearlStock = 4
GlassFurnaceMaker.productStock = {}; GlassFurnaceMaker.buildings = {}; GlassFurnaceMaker.maker = nil; GlassFurnaceMaker.activeMaking = {}; GlassFurnaceMaker.totalProducts = 0; GlassFurnaceMaker.dayTimer = 0
function GlassFurnaceMaker.init() GlassFurnaceMaker.brickStock=18; GlassFurnaceMaker.clayStock=12; GlassFurnaceMaker.woodStock=14; GlassFurnaceMaker.ironStock=12; GlassFurnaceMaker.silverStock=6; GlassFurnaceMaker.goldStock=6; GlassFurnaceMaker.jewelStock=4; GlassFurnaceMaker.pearlStock=4; GlassFurnaceMaker.productStock={}; GlassFurnaceMaker.buildings={}; GlassFurnaceMaker.maker=nil; GlassFurnaceMaker.activeMaking={}; GlassFurnaceMaker.totalProducts=0; GlassFurnaceMaker.dayTimer=0; print("[GlassFurnaceMaker] Royal Glass Furnace Maker System initialized (6 products, 4 buildings)") end
function GlassFurnaceMaker.hireMaker(n,s) s=s or math.random(55,90); local c=640+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassFurnaceMaker.maker={name=n or ("Pečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečar najet: %s (spretnost: %d)",GlassFurnaceMaker.maker.name,s),"success") end; return true end
function GlassFurnaceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassFurnaceMaker.build(id) local ok,e=GlassFurnaceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassFurnaceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassFurnaceMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassFurnaceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassFurnaceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brickCost and GlassFurnaceMaker.brickStock<(d.brickCost or 0) then return false,"Premalo opek" end; if d.clayCost and GlassFurnaceMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.woodCost and GlassFurnaceMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and GlassFurnaceMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and GlassFurnaceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassFurnaceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassFurnaceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassFurnaceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassFurnaceMaker.buildings==0 then return false,"Potrebna pečna delavnica" end; if not GlassFurnaceMaker.maker then return false,"Potreben pečar" end; return true end
function GlassFurnaceMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassFurnaceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brickCost then GlassFurnaceMaker.brickStock=GlassFurnaceMaker.brickStock-d.brickCost*qty end; if d.clayCost then GlassFurnaceMaker.clayStock=GlassFurnaceMaker.clayStock-d.clayCost*qty end; if d.woodCost then GlassFurnaceMaker.woodStock=GlassFurnaceMaker.woodStock-d.woodCost*qty end; if d.ironCost then GlassFurnaceMaker.ironStock=GlassFurnaceMaker.ironStock-d.ironCost*qty end; if d.silverCost then GlassFurnaceMaker.silverStock=GlassFurnaceMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassFurnaceMaker.goldStock=GlassFurnaceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassFurnaceMaker.jewelStock=GlassFurnaceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassFurnaceMaker.pearlStock=GlassFurnaceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassFurnaceMaker.maker then t=math.max(1,t-math.floor(GlassFurnaceMaker.maker.skill/12)) end; table.insert(GlassFurnaceMaker.activeMaking,{id="glassfurnace_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassFurnaceMaker.completeMaking(m) local q=1.0+(GlassFurnaceMaker.getQualityBonus()/100); if GlassFurnaceMaker.maker then q=q+(GlassFurnaceMaker.maker.skill/140) end; q=math.min(2.5,q); GlassFurnaceMaker.productStock[m.productType]=(GlassFurnaceMaker.productStock[m.productType] or 0)+m.quantity; GlassFurnaceMaker.totalProducts=GlassFurnaceMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassFurnaceMaker.maker then GlassFurnaceMaker.maker.itemsMade=GlassFurnaceMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassFurnaceMaker.maker.skill=math.min(100,GlassFurnaceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklarska peč izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassfurnace.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function GlassFurnaceMaker.update(dt) if not _G.state then return end; GlassFurnaceMaker.dayTimer=GlassFurnaceMaker.dayTimer+dt; if GlassFurnaceMaker.dayTimer>=30 then GlassFurnaceMaker.dayTimer=0; for i=#GlassFurnaceMaker.activeMaking,1,-1 do local m=GlassFurnaceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassFurnaceMaker.completeMaking(m); table.remove(GlassFurnaceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassFurnaceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassFurnaceMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassFurnaceMaker.getStats() return {brickStock=GlassFurnaceMaker.brickStock,clayStock=GlassFurnaceMaker.clayStock,woodStock=GlassFurnaceMaker.woodStock,ironStock=GlassFurnaceMaker.ironStock,silverStock=GlassFurnaceMaker.silverStock,goldStock=GlassFurnaceMaker.goldStock,jewelStock=GlassFurnaceMaker.jewelStock,pearlStock=GlassFurnaceMaker.pearlStock,productStock=GlassFurnaceMaker.productStock,numBuildings=#GlassFurnaceMaker.buildings,hasMaker=GlassFurnaceMaker.maker~=nil,makerName=GlassFurnaceMaker.maker and GlassFurnaceMaker.maker.name or "—",makerSkill=GlassFurnaceMaker.maker and GlassFurnaceMaker.maker.skill or 0,activeMaking=#GlassFurnaceMaker.activeMaking,totalProducts=GlassFurnaceMaker.totalProducts} end
return GlassFurnaceMaker
